package com.example.insurance.service.impl;

import com.example.insurance.service.ClaimService;
import com.example.insurance.entity.*; import com.example.insurance.repository.*; import com.example.insurance.exception.ResourceNotFoundException; import org.springframework.stereotype.Service;
import java.util.List; import java.util.*;
@Service public class ClaimServiceImpl implements ClaimService {private final ClaimRepository repo;private final PolicyRepository policies;public ClaimServiceImpl(ClaimRepository r,PolicyRepository p){repo=r;policies=p;} public List<Claim> getAll(){return repo.findAll();} public Claim getById(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Claim not found: "+id));} public List<Claim> getByPolicyId(Long id){if(!policies.existsById(id))throw new ResourceNotFoundException("Policy not found: "+id);return repo.findByPolicyPolicyId(id);} public Claim create(Long policyId,Claim c){Policy p=policies.findById(policyId).orElseThrow(()->new ResourceNotFoundException("Policy not found: "+policyId));c.setClaimId(null);c.setPolicy(p);if(c.getClaimStatus()==null)c.setClaimStatus("PENDING");return repo.save(c);} public Claim update(Long id,Claim x){Claim c=getById(id);if(!"PENDING".equalsIgnoreCase(c.getClaimStatus()))throw new IllegalArgumentException("Only pending claims can be edited");c.setClaimAmount(x.getClaimAmount());c.setClaimDate(x.getClaimDate());c.setAccidentLocation(x.getAccidentLocation());c.setDescription(x.getDescription());return repo.save(c);} public Claim updateStatus(Long id,String s){Claim c=getById(id);c.setClaimStatus(s.toUpperCase());return repo.save(c);} public void delete(Long id){repo.delete(getById(id));}}
